import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int k = in.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[in.nextInt()] = 1;
        }
        int[] ans = {1};
        int exp = n / 2;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                ans = multiply(ans, v, 998244353);
            }
            v = multiply(v, v, 998244353);
            exp >>= 1;
        }
        long total = 0;
        for (int x : ans) {
            total = (total + (long) x * x) % 998244353;
        }
        out.println(total);
        out.close();
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = 1;
        while (n < need) n <<= 1;

        double[] ar = new double[n], ai = new double[n];
        double[] br = new double[n], bi = new double[n];

        for (int i = 0; i < a.length; i++) {
            long x = ((a[i] % mod) + mod) % mod;
            ar[i] = x & 0x7FFF;
            ai[i] = x >>> 15;
        }
        for (int i = 0; i < b.length; i++) {
            long x = ((b[i] % mod) + mod) % mod;
            br[i] = x & 0x7FFF;
            bi[i] = x >>> 15;
        }

        fft(ar, ai, false);
        fft(br, bi, false);

        double[] res1r = new double[n], res1i = new double[n];
        double[] res2r = new double[n], res2i = new double[n];

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);
            double a1r = (ar[i] + ar[j]) * 0.5;
            double a1i = (ai[i] - ai[j]) * 0.5;
            double a2r = (ai[i] + ai[j]) * 0.5;
            double a2i = (ar[j] - ar[i]) * 0.5;

            double b1r = (br[i] + br[j]) * 0.5;
            double b1i = (bi[i] - bi[j]) * 0.5;
            double b2r = (bi[i] + bi[j]) * 0.5;
            double b2i = (br[j] - br[i]) * 0.5;

            res1r[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            res1i[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            res2r[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            res2i[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(res1r, res1i, true);
        fft(res2r, res2i, true);

        int[] result = new int[need];
        for (int i = 0; i < need; i++) {
            long aa = Math.round(res1r[i]);
            long bb = Math.round(res2r[i]);
            long cc = Math.round(res1i[i]);
            result[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return result;
    }

    void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        int bits = 32 - Integer.numberOfTrailingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i) >>> bits;
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double angle = 2 * Math.PI * j / len;
                    double wRe = Math.cos(angle);
                    double wIm = inv ? -Math.sin(angle) : Math.sin(angle);

                    double uRe = re[i + j];
                    double uIm = im[i + j];
                    double vRe = re[i + j + half] * wRe - im[i + j + half] * wIm;
                    double vIm = re[i + j + half] * wIm + im[i + j + half] * wRe;

                    re[i + j] = uRe + vRe;
                    im[i + j] = uIm + vIm;
                    re[i + j + half] = uRe - vRe;
                    im[i + j + half] = uIm - vIm;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (len <= 0) return -1;
            }
            return buf[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new RuntimeException();
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}
